ui.addEventListener('pointerdown',e=>{const button=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-action="feed"]');if(e.button===0&&mode==='game'&&button&&!button.disabled&&reefBodyEnabled(state)&&has(state.player.genome,'filter'))pointerPump=true;});
